{
  "headline": "FDA's records show a registered plant on our fosphenytoin sodium labels received a Warning Letter 3427 days before the posting",
  "headline_cites": ["E13", "D1"],
  "sentences": [
    {
      "text": "Corvale East has 19 days of fosphenytoin sodium on hand at current use, Corvale General has 24 days, and Corvale Lakeside has 19 days.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "One of our labeled products is manufactured at GLAND by Sagent Pharmaceuticals.",
      "cites": ["E7"]
    },
    {
      "text": "Another labeled product is relabeled and repacked by A-S Medication Solutions at FEI 1450743, a registered plant in the USA.",
      "cites": ["E14"]
    },
    {
      "text": "FDA inspected that plant on 2026-08-12 and classified it VAI, with the inspection known to FDA on 2026-10-14.",
      "cites": ["E12"]
    },
    {
      "text": "FDA issued a Warning Letter to that plant on 2017-06-05, which was 3427 days before the posting date.",
      "cites": ["E13", "D1"]
    },
    {
      "text": "The plant also has a history of VAI inspections in 2009, 2012, 2013, and 2018.",
      "cites": ["E8", "E9", "E10", "E11"]
    }
  ]
}
